From 5c9671ee3337edfa01a0c7f2393f94100c74fa65 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:13:43 +0100
Subject: [PATCH] wayland: give each idle timeout its own notification

Timeouts of the same length shared one Wayland idle notification, so a
new one counted from when the first was added, or never fired if that
had already gone idle. Pollers can now key timeouts by registration id.

BUG: 527667
---
 src/kabstractidletimepoller_p.h | 19 +++++++++++++++
 src/kidletime.cpp               | 41 +++++++++++++++++++++++++++++++--
 src/plugins/wayland/poller.cpp  | 25 ++++++++++++--------
 src/plugins/wayland/poller.h    |  7 ++++--
 4 files changed, 79 insertions(+), 13 deletions(-)

diff --git a/src/kabstractidletimepoller_p.h b/src/kabstractidletimepoller_p.h
index cef6179..13e9906 100644
--- a/src/kabstractidletimepoller_p.h
+++ b/src/kabstractidletimepoller_p.h
@@ -40,8 +40,27 @@ public Q_SLOTS:
 Q_SIGNALS:
     void resumingFromIdle();
     void timeoutReached(int msec);
+    void registeredTimeoutReached(int identifier);
 };

 Q_DECLARE_INTERFACE(KAbstractIdleTimePoller, KAbstractIdleTimePoller_iid)

+#define KRegisteredIdleTimePoller_iid "org.kde.kidletime.KRegisteredIdleTimePoller"
+
+/*
+ * Implemented by pollers whose idle timeouts count from when they are added, so that every
+ * KIdleTime::addIdleTimeout() call gets its own timeout instead of sharing one with the same length.
+ * Such pollers emit registeredTimeoutReached() instead of timeoutReached().
+ */
+class KRegisteredIdleTimePoller
+{
+public:
+    virtual ~KRegisteredIdleTimePoller() = default;
+
+    virtual void addRegisteredTimeout(int identifier, int msec) = 0;
+    virtual void removeRegisteredTimeout(int identifier) = 0;
+};
+
+Q_DECLARE_INTERFACE(KRegisteredIdleTimePoller, KRegisteredIdleTimePoller_iid)
+
 #endif /* KABSTRACTIDLETIMEPOLLER_P_H */
diff --git a/src/kidletime.cpp b/src/kidletime.cpp
index 73eb194..9c4d875 100644
--- a/src/kidletime.cpp
+++ b/src/kidletime.cpp
@@ -61,6 +61,12 @@ public:
     void unloadCurrentSystem();
     void resumingFromIdle();
     void timeoutReached(int msec);
+    void registeredTimeoutReached(int identifier);
+
+    KRegisteredIdleTimePoller *registeredPoller() const
+    {
+        return qobject_cast<KRegisteredIdleTimePoller *>(poller.data());
+    }

     QPointer<KAbstractIdleTimePoller> poller;
     bool catchResume;
@@ -87,6 +93,9 @@ KIdleTime::KIdleTime()
     connect(d->poller.data(), &KAbstractIdleTimePoller::timeoutReached, this, [d](int msec) {
         d->timeoutReached(msec);
     });
+    connect(d->poller.data(), &KAbstractIdleTimePoller::registeredTimeoutReached, this, [d](int identifier) {
+        d->registeredTimeoutReached(identifier);
+    });
 }

 KIdleTime::~KIdleTime()
@@ -126,9 +135,14 @@ int KIdleTime::addIdleTimeout(int msec)
         return 0;
     }

-    d->poller.data()->addTimeout(msec);
-
     ++d->currentId;
+
+    if (auto registeredPoller = d->registeredPoller()) {
+        registeredPoller->addRegisteredTimeout(d->currentId, msec);
+    } else {
+        d->poller.data()->addTimeout(msec);
+    }
+
     d->associations[d->currentId] = msec;

     return d->currentId;
@@ -147,6 +161,11 @@ void KIdleTime::removeIdleTimeout(int identifier)

     d->associations.erase(it);

+    if (auto registeredPoller = d->registeredPoller()) {
+        registeredPoller->removeRegisteredTimeout(identifier);
+        return;
+    }
+
     const bool isFound = std::any_of(d->associations.cbegin(), d->associations.cend(), [msec](int i) {
         return i == msec;
     });
@@ -160,6 +179,14 @@ void KIdleTime::removeAllIdleTimeouts()
 {
     Q_D(KIdleTime);

+    if (auto registeredPoller = d->registeredPoller()) {
+        for (auto it = d->associations.cbegin(); it != d->associations.cend(); ++it) {
+            registeredPoller->removeRegisteredTimeout(it.key());
+        }
+        d->associations.clear();
+        return;
+    }
+
     std::vector<int> removed;

     for (auto it = d->associations.cbegin(); it != d->associations.cend(); ++it) {
@@ -299,6 +326,16 @@ void KIdleTimePrivate::timeoutReached(int msec)
     }
 }

+void KIdleTimePrivate::registeredTimeoutReached(int identifier)
+{
+    Q_Q(KIdleTime);
+
+    const auto it = associations.constFind(identifier);
+    if (it != associations.cend()) {
+        Q_EMIT q->timeoutReached(identifier, it.value());
+    }
+}
+
 void KIdleTime::simulateUserActivity()
 {
     Q_D(KIdleTime);
diff --git a/src/plugins/wayland/poller.cpp b/src/plugins/wayland/poller.cpp
index 86294fc..7404a22 100644
--- a/src/plugins/wayland/poller.cpp
+++ b/src/plugins/wayland/poller.cpp
@@ -131,25 +131,32 @@ bool Poller::isAvailable()

 void Poller::addTimeout(int nextTimeout)
 {
-    if (m_timeouts.contains(nextTimeout)) {
-        return;
-    }
+    // KIdleTime uses addRegisteredTimeout() with this poller
+    Q_UNUSED(nextTimeout)
+}

-    auto timeout = createTimeout(nextTimeout);
+void Poller::removeTimeout(int nextTimeout)
+{
+    Q_UNUSED(nextTimeout)
+}
+
+void Poller::addRegisteredTimeout(int identifier, int msec)
+{
+    auto timeout = createTimeout(msec);
     if (!timeout) {
         return;
     }

-    connect(timeout, &IdleTimeout::idle, this, [this, nextTimeout] {
-        Q_EMIT timeoutReached(nextTimeout);
+    connect(timeout, &IdleTimeout::idle, this, [this, identifier] {
+        Q_EMIT registeredTimeoutReached(identifier);
     });
     connect(timeout, &IdleTimeout::resumeFromIdle, this, &Poller::resumingFromIdle);
-    m_timeouts.insert(nextTimeout, QSharedPointer<IdleTimeout>(timeout));
+    m_timeouts.insert(identifier, QSharedPointer<IdleTimeout>(timeout));
 }

-void Poller::removeTimeout(int nextTimeout)
+void Poller::removeRegisteredTimeout(int identifier)
 {
-    m_timeouts.remove(nextTimeout);
+    m_timeouts.remove(identifier);
 }

 QList<int> Poller::timeouts() const
diff --git a/src/plugins/wayland/poller.h b/src/plugins/wayland/poller.h
index 60d4842..4572335 100644
--- a/src/plugins/wayland/poller.h
+++ b/src/plugins/wayland/poller.h
@@ -15,11 +15,11 @@ class IdleManagerExt;

 class IdleTimeout;

-class Poller : public KAbstractIdleTimePoller
+class Poller : public KAbstractIdleTimePoller, public KRegisteredIdleTimePoller
 {
     Q_OBJECT
     Q_PLUGIN_METADATA(IID KAbstractIdleTimePoller_iid FILE "wayland.json")
-    Q_INTERFACES(KAbstractIdleTimePoller)
+    Q_INTERFACES(KAbstractIdleTimePoller KRegisteredIdleTimePoller)

 public:
     explicit Poller(QObject *parent = nullptr);
@@ -31,6 +31,9 @@ public:
     }
     void unloadPoller() override {}

+    void addRegisteredTimeout(int identifier, int msec) override;
+    void removeRegisteredTimeout(int identifier) override;
+
 public Q_SLOTS:
     void addTimeout(int nextTimeout) override;
     void removeTimeout(int nextTimeout) override;
-- 
